            "SELECT (AVG(?y) AS ?c) WHERE { ?x knows ?y }", "聚合"
        )
        self.assertQueryError(
            "SELECT (MIN(*) AS ?c) WHERE { ?x knows ?y }", "MIN"
        )
        self.assertQueryError(
            "SELECT (MAX(*) AS ?c) WHERE { ?x knows ?y }", "MAX"
        )
        self.assertQueryError(
