        )
        self.assertQueryError(
            "SELECT (MIN(DISTINCT ?y) AS ?c) WHERE { ?x knows ?y }", "DISTINCT"
        )
        self.assertQueryError(
            "SELECT (COUNT(?y ?x) AS ?c) WHERE { ?x knows ?y }", "非法"
        )
        self.assertQueryError(
