                   {"subject":"b","predicate":"knows","object":"c"}], "rules": []}
m = OntologyEngine().parse(json.dumps(doc))

# plain var alongside aggregate without GROUP BY -> error
for t in [
  "SELECT ?x (COUNT(*) AS ?c) WHERE { ?x knows ?y }",
  "SELECT ?x WHERE { ?x knows ?y } GROUP BY ?y",
  # aggregate must keep WHERE body errors
  "SELECT (COUNT(*) AS ?c) WHERE { ?x hates ?y }",
  "SELECT (COUNT(*) AS ?c) WHERE { }",
  # ASK/CONSTRUCT/DESCRIBE reject GROUP BY
]:
    try:
