  "ASK WHERE { ?x knows ?y } GROUP BY ?x",
  "CONSTRUCT { ?x knows ?y } WHERE { ?x knows ?y } GROUP BY ?x",
  "DESCRIBE ?x WHERE { ?x knows ?y } ORDER BY ?x",
]:
    fn = m.ask if t.startswith("ASK") else (m.construct if t.startswith("CONSTRUCT") else m.describe)
    try:
        fn(t); print("NO ERROR:", t)
    except OntologyError as e:
        print("OK:", str(e).split("（字符位置")[0])

